import * as React from "react";
import { CommonProps } from "../utility/commonProps";
export interface BreadcrumbProps extends React.ComponentPropsWithoutRef<"nav">, CommonProps {
    /**
     * The content for the breadcrumb.
     */
    children: React.ReactNode;
}
/**
 * The breadcrumb is a secondary navigation pattern that helps a user understand the hierarchy among levels and navigate back through them. Breadcrumbs show users their current location relative to the information architecture and enable them to quickly move up to a parent level or previous step.
 *
 * - {@link https://livingdesign.walmart.com/components/breadcrumb/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/breadcrumb/react/ React documentation}
 *
 * ### Content
 *
 * The Breadcrumb accepts content as Bread Crumb Item components through a required `children` prop:
 *
 * ```tsx
 * <Breadcrumb>
 *   <BreadcrumbItem href="https://www.walmart.com/">
 *     Home
 *   </BreadcrumbItem>
 *   <BreadcrumbItem href="https://www.walmart.com/all-departments">
 *     Departments
 *   </BreadcrumbItem>
 * </Breadcrumb>
 * ```
 */
export declare const Breadcrumb: React.FunctionComponent<BreadcrumbProps>;
